package org.springframework.samples.petclinic.rest.function.owner;

import java.util.concurrent.atomic.AtomicLong;

import net.officefloor.plugin.variable.Val;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.samples.petclinic.model.Owner;

import tools.jackson.databind.json.JsonMapper;

/**
 * Emits, on the dedicated {@code AUDIT} logger, the record of a newly created owner. Runs after the
 * owner has been saved so its id is available. Two things are emitted:
 *
 * <ol>
 * <li>a human-readable audit line (id, memberId, registrationDate, membershipLevel); and</li>
 * <li>an immutable structured {@link OwnerCreatedEvent} serialised to JSON, so audit consumers have a
 * machine-parseable, ordered event to react to.</li>
 * </ol>
 */
public class AuditOwnerCreated {

    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");

    private static final JsonMapper JSON = JsonMapper.builder().build();

    /** Monotonically increasing sequence stamped onto each event, shared across all creates. */
    private static final AtomicLong SEQUENCE = new AtomicLong();

    public void service(@Val Owner owner) {
        int membershipLevel = OwnerMembership.level(owner);

        AUDIT.info(
                "Created owner id={} memberId={} registrationDate={} membershipLevel={}",
                owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), membershipLevel);

        OwnerCreatedEvent event = new OwnerCreatedEvent(SEQUENCE.incrementAndGet(), owner.getId(),
                primaryIdentifier(owner), membershipLevel);
        AUDIT.info(JSON.writeValueAsString(event));
    }

    /**
     * The owner's primary identifier carried by the {@link OwnerCreatedEvent} — the unified
     * {@code memberId}. This single method is the one place the event's identity source is defined.
     */
    private static String primaryIdentifier(Owner owner) {
        return owner.getMemberId();
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.HashSet;
import java.util.Set;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns the owner's unified {@code memberId}, formatted {@code <REGION><FY><HASH8><CHK>} — the
 * region code derived from the postcode (NSW/VIC/QLD, else {@code UNKNOWN}), the two-digit fiscal year
 * the registrationDate falls in, the first 8 upper-case hex characters of SHA-256 over
 * {@code normalizedTelephone + lastName}, and a single Luhn check digit over the digits of
 * {@code <REGION><FY><HASH8>} (see {@link MemberId}, e.g. {@code NSW271A2B3C4D5}). The base id is fully
 * determined by the owner's region, fiscal year and hashed identity.
 *
 * <p>When that base id collides with an existing owner's {@code memberId}, it is de-duplicated by
 * appending {@code -<n>} with the smallest {@code n} of 2 or more that makes it unique (e.g.
 * {@code NSW271A2B3C4D5-2}). Runs before {@link SaveOwner}, so {@link OwnerRepository#findAll()}
 * returns only the owners that predate this create.
 */
public class AssignMemberId {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        owner.setMemberId(uniqueId(baseId(owner), assignedIds(ownerRepository)));
    }

    /**
     * The owner's base memberId before any collision suffix, formatted {@code <REGION><FY><HASH8><CHK>}.
     * Fully determined by the owner, so equal owners produce the same base.
     */
    private static String baseId(Owner owner) {
        String region = OwnerRegion.fromPostcode(owner.getPostcode());
        if (region == null) {
            region = "UNKNOWN";
        }
        String fiscalYearCode = OwnerMembership.fiscalYearCode(owner.getRegistrationDate());
        String hash8 = OwnerIdentity.customerHash(owner.getTelephone(), owner.getLastName());
        return MemberId.of(region, fiscalYearCode, hash8);
    }

    /**
     * {@code base} de-duplicated against {@code existing} by appending {@code -<n>} with the smallest
     * {@code n} of 2 or more that makes it unique (e.g. {@code NSW271A2B3C4D5-2}); {@code base} itself
     * when already free.
     */
    private static String uniqueId(String base, Set<String> existing) {
        String id = base;
        for (int n = 2; existing.contains(id); n++) {
            id = base + "-" + n;
        }
        return id;
    }

    /** The ids already assigned to existing owners — the set a new memberId must avoid colliding with. */
    private static Set<String> assignedIds(OwnerRepository ownerRepository) {
        Set<String> existing = new HashSet<>();
        for (Owner other : ownerRepository.findAll()) {
            if (other.getMemberId() != null) {
                existing.add(other.getMemberId());
            }
        }
        return existing;
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

/**
 * The single source of truth for an owner's unified {@code memberId}, formatted
 * {@code <REGION><FY><HASH8><CHK>}: REGION is the region code derived from the postcode
 * (NSW/VIC/QLD, else {@code UNKNOWN}), FY the two-digit fiscal year, HASH8 the first 8 upper-case
 * hex characters of SHA-256 over {@code normalizedTelephone + lastName} (the same HASH8 the
 * region-and-hash identity uses — see {@link OwnerIdentity#customerHash}), and CHK a single Luhn
 * check digit over the decimal digits of {@code <REGION><FY><HASH8>}.
 *
 * <p>{@link #of} assembles the id from its parts when an owner is created; {@link #regionOf} and
 * {@link #fiscalYearCodeOf} read the REGION and FY segments back out of an assigned id, which is how
 * the owner's locality, timezone and fiscal year all resolve straight off the memberId. A collision
 * with an existing owner's memberId is de-duplicated by appending {@code -<n>} (see
 * {@link AssignMemberId}); the suffix is not part of the segments the readers below extract.
 */
public final class MemberId {

    /** The fixed-width tail after the REGION prefix: FY (2) + HASH8 (8) + CHK (1). */
    private static final int TAIL_LENGTH = 11;

    private MemberId() {
    }

    /**
     * The base memberId {@code <REGION><FY><HASH8><CHK>} assembled from its parts (before any
     * collision suffix): CHK is the Luhn check digit over the decimal digits of
     * {@code region + fiscalYearCode + hash8}.
     */
    public static String of(String region, String fiscalYearCode, String hash8) {
        String core = region + fiscalYearCode + hash8;
        return core + OwnerIdentity.luhnCheckDigit(core);
    }

    /**
     * The REGION prefix of {@code memberId} — one of the known regions (NSW, VIC, QLD), else
     * {@code UNKNOWN} (which also covers an absent or malformed id).
     */
    public static String regionOf(String memberId) {
        if (memberId != null) {
            for (String region : OwnerRegion.knownRegions()) {
                if (memberId.startsWith(region)) {
                    return region;
                }
            }
        }
        return "UNKNOWN";
    }

    /**
     * The two-digit FY segment of {@code memberId}: the two characters immediately after the REGION
     * prefix. Null when the id is absent or too short to carry the FY segment (before the HASH8/CHK
     * tail).
     */
    public static String fiscalYearCodeOf(String memberId) {
        if (memberId == null) {
            return null;
        }
        int start = regionOf(memberId).length();
        if (memberId.length() < start + TAIL_LENGTH) {
            return null;
        }
        return memberId.substring(start, start + 2);
    }
}
